// Example of a stateless service design for horizontal scaling
@RestController
public class OrderController {
    // Do NOT store state in a private field here, as it won't be shared across nodes
    private final OrderRepository repository;

    public OrderController(OrderRepository repository) {
        this.repository = repository;
    }

    @PostMapping("/orders")
    public ResponseEntity<Order> createOrder(@RequestBody Order order) {
        // State is persisted in a shared database, allowing any node to handle the request
        return ResponseEntity.ok(repository.save(order));
    }
}
